import sys


def main():
    group_of = {}
    groups = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        names = line.split()
        if len(names) == 1:
            name = names[0]
            if name not in group_of:
                group_of[name] = len(groups)
                groups.append(set())
                groups[-1].add(name)
        else:
            first, last = names[0], names[-1]
            if first in group_of:
                g = group_of[first]
            elif last in group_of:
                g = group_of[last]
            else:
                g = len(groups)
                groups.append(set())
            for name in names:
                group_of[name] = g
                groups[g].add(name)
    groups.sort(key=lambda s: (-len(s), min(s)))
    for group in groups:
        print(" ".join(sorted(group)))


if __name__ == "__main__":
    main()
